import React from "react";
import { FaLinkedin, FaGithub, FaEnvelope } from "react-icons/fa";

const Footer = () => {
  return (
    <>
      <style>{`
        .footer {
          background: #0f172a;
          color: #cbd5e1;
          padding: 28px 8%;
          border-top: 1px solid rgba(255,255,255,0.08);
        }

        .footer-top {
          display: flex;
          justify-content: space-between;
          align-items: center;
          flex-wrap: wrap;
          gap: 20px;
        }

        .footer-left h3 {
          font-size: 1.2rem;
          margin: 0 0 6px 0;
          color: #ffffff;
        }

        .footer-left p {
          font-size: 0.85rem;
          margin: 0;
          color: #94a3b8;
        }

        .footer-right {
          display: flex;
          gap: 18px;
        }

        .footer-right a {
          width: 36px;
          height: 36px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 50%;
          background: rgba(255,255,255,0.05);
          color: #cbd5e1;
          font-size: 0.95rem;
          transition: all 0.3s ease;
        }

        .footer-right a:hover {
          background: #2563eb;
          color: #ffffff;
          transform: translateY(-3px);
        }

        .footer-bottom {
          text-align: center;
          margin-top: 20px;
          font-size: 0.75rem;
          color: #64748b;
        }

        @media (max-width: 768px) {
          .footer-top {
            flex-direction: column;
            align-items: center;
            text-align: center;
          }

          .footer-right {
            margin-top: 10px;
          }
        }
      `}</style>

      <footer className="footer">

        <div className="footer-top">

          <div className="footer-left">
            <h3>Swetha</h3>
            <p>Crafting scalable digital experiences.</p>
          </div>

          <div className="footer-right">
            <a href="mailto:swethaa1805@email.com">
              <FaEnvelope />
            </a>

            <a
              href="https://www.linkedin.com/in/swetha-a-0b1712382/"
              target="_blank"
              rel="noopener noreferrer"
            >
              <FaLinkedin />
            </a>

            <a
              href="https://github.com/Swethaa1805"
              target="_blank"
              rel="noopener noreferrer"
            >
              <FaGithub />
            </a>
          </div>

        </div>

        <div className="footer-bottom">
          © {new Date().getFullYear()} Swetha
        </div>

      </footer>
    </>
  );
};

export default Footer;
